-- HR conversion-readiness rules v0.1 compiled for duckdb
-- Reference engine; executed by run_checks.py in this repository.
-- transpiler: none (hand-authored portable SQL, tokens rendered)
-- Generated by compile_rules.py from rules/catalog.yaml and rules/source_map.yaml. Do not edit.

-- 1. Staging views (logical names -> physical EDW tables)
CREATE OR REPLACE VIEW stg_person AS SELECT EDW_PERS_ID AS pers_id, PERS_EFF_DT AS eff_dt, NATL_ID_HASH AS natl_id_hash, PERS_FIRST_NAME AS first_name, PERS_LAST_NAME AS last_name, BIRTH_DT AS birth_dt, COALESCE(PERS_EXP_DT, DATE '9999-12-31') AS exp_dt, CASE WHEN COALESCE(PERS_EXP_DT, DATE '9999-12-31') >= DATE '9999-12-31' THEN DATE '9999-12-31' ELSE CAST(COALESCE(PERS_EXP_DT, DATE '9999-12-31') + INTERVAL 1 DAY AS DATE) END AS exp_next_dt FROM edw.T_PERS_HIST;
CREATE OR REPLACE VIEW stg_employee AS SELECT EDW_PERS_ID AS pers_id, EMPEE_EFF_DT AS eff_dt, EMPEE_STATUS_CD AS status_cd, EMPEE_CLS_CD AS ecls_cd, FIRST_HIRE_DT AS first_hire_dt, CUR_HIRE_DT AS cur_hire_dt, HOME_ORG_CD AS home_org_cd, COALESCE(EMPEE_EXP_DT, DATE '9999-12-31') AS exp_dt, CASE WHEN COALESCE(EMPEE_EXP_DT, DATE '9999-12-31') >= DATE '9999-12-31' THEN DATE '9999-12-31' ELSE CAST(COALESCE(EMPEE_EXP_DT, DATE '9999-12-31') + INTERVAL 1 DAY AS DATE) END AS exp_next_dt FROM edw.T_EMPEE_HIST;
CREATE OR REPLACE VIEW stg_termination AS SELECT EDW_PERS_ID AS pers_id, TERM_DT AS term_dt, TERM_REASON_CD AS term_reason_cd, SURS_RETIR_IND AS surs_retir_ind FROM edw.T_EMPEE_HIST_5;
CREATE OR REPLACE VIEW stg_job AS SELECT EDW_PERS_ID AS pers_id, POSN_NBR AS posn_nbr, JOB_SUFFIX AS suffix, JOB_DETL_EFF_DT AS eff_dt, JOB_CONTRACT_TYPE_CD AS contract_type, JOB_STATUS_CD AS status_cd, JOB_FTE AS fte, JOB_ANNUAL_SAL_AMT AS annual_sal, JOB_CLS_CD AS class_cd, JOB_ECLS_CD AS ecls_cd, JOB_ORG_CD AS org_cd, SUPERVISOR_PERS_ID AS supervisor_pers_id, COALESCE(JOB_DETL_EXP_DT, DATE '9999-12-31') AS exp_dt, CASE WHEN COALESCE(JOB_DETL_EXP_DT, DATE '9999-12-31') >= DATE '9999-12-31' THEN DATE '9999-12-31' ELSE CAST(COALESCE(JOB_DETL_EXP_DT, DATE '9999-12-31') + INTERVAL 1 DAY AS DATE) END AS exp_next_dt FROM edw.T_JOB_DETL_HIST;
CREATE OR REPLACE VIEW stg_position AS SELECT POSN_NBR AS posn_nbr, POSN_EFF_DT AS eff_dt, POSN_STATUS_CD AS status_cd, POSN_CLS_CD AS class_cd, POSN_ORG_CD AS org_cd, POSN_BUDGET_FTE AS budget_fte, COALESCE(POSN_EXP_DT, DATE '9999-12-31') AS exp_dt, CASE WHEN COALESCE(POSN_EXP_DT, DATE '9999-12-31') >= DATE '9999-12-31' THEN DATE '9999-12-31' ELSE CAST(COALESCE(POSN_EXP_DT, DATE '9999-12-31') + INTERVAL 1 DAY AS DATE) END AS exp_next_dt FROM edw.T_POSN_HIST;
CREATE OR REPLACE VIEW stg_pay AS SELECT EDW_PERS_ID AS pers_id, POSN_NBR AS posn_nbr, JOB_SUFFIX AS suffix, PAY_PERIOD_END_DT AS period_end_dt, EARN_CD AS earn_cd, PAY_AMT AS amount, ORG_CD AS org_cd, PAYR_SEQ_NBR AS seq_nbr FROM edw.T_PAYR_ACCTG_DETL;
CREATE OR REPLACE VIEW ref_class AS SELECT CLS_CD AS class_cd, CLS_SOURCE AS class_source, CLS_TITLE AS class_title, MIN_ANNUAL_AMT AS min_annual, MAX_ANNUAL_AMT AS max_annual FROM edw.REF_JOB_CLASS;
CREATE OR REPLACE VIEW ref_ecls AS SELECT ECLS_CD AS ecls_cd, ECLS_GROUP AS ecls_group, PAY_BASIS AS pay_basis, ECLS_DESC AS ecls_desc FROM edw.REF_EMPEE_CLS;
CREATE OR REPLACE VIEW ref_org AS SELECT ORG_CD AS org_cd, PARENT_ORG_CD AS parent_org_cd, ORG_STATUS_CD AS status_cd, ORG_TITLE AS org_title FROM edw.REF_ORG;
CREATE OR REPLACE VIEW ref_hierarchy_root AS SELECT POSN_NBR AS posn_nbr FROM edw.REF_HIERARCHY_ROOT;

-- 2. Helper views
CREATE OR REPLACE VIEW cur_emp AS
SELECT * FROM stg_employee WHERE eff_dt <= DATE '2026-10-31' AND exp_dt >= DATE '2026-10-31';
CREATE OR REPLACE VIEW cur_person AS
SELECT * FROM stg_person WHERE eff_dt <= DATE '2026-10-31' AND exp_dt >= DATE '2026-10-31';
CREATE OR REPLACE VIEW cur_job AS
SELECT j.*, j.pers_id || '|' || j.posn_nbr || '|' || j.suffix AS job_key
FROM stg_job j
WHERE j.eff_dt <= DATE '2026-10-31' AND j.exp_dt >= DATE '2026-10-31' AND j.status_cd IN ('A', 'L');
CREATE OR REPLACE VIEW cur_posn AS
SELECT * FROM stg_position WHERE eff_dt <= DATE '2026-10-31' AND exp_dt >= DATE '2026-10-31';
CREATE OR REPLACE VIEW active_worker AS
SELECT DISTINCT e.pers_id FROM cur_emp e
WHERE e.status_cd IN ('A', 'L') AND EXISTS (SELECT 1 FROM cur_job j WHERE j.pers_id = e.pers_id);

-- 3. Rules (each returns entity_type, entity_id, detail)

-- P01 [critical] Same national-ID hash on more than one person ID
SELECT 'person' AS entity_type, p.pers_id AS entity_id,
       'national-id hash shared by ' || CAST(g.n AS VARCHAR(10)) || ' person ids' AS detail
FROM (SELECT DISTINCT pers_id, natl_id_hash FROM stg_person WHERE natl_id_hash IS NOT NULL) p
JOIN (SELECT natl_id_hash, COUNT(DISTINCT pers_id) AS n FROM stg_person
      WHERE natl_id_hash IS NOT NULL GROUP BY natl_id_hash HAVING COUNT(DISTINCT pers_id) > 1) g
  ON g.natl_id_hash = p.natl_id_hash;

-- P02 [high] Probable duplicate person (same name and birth date, different national-ID hash)
SELECT 'person' AS entity_type, p.pers_id AS entity_id,
       'name+birth date shared with another person id' AS detail
FROM (SELECT DISTINCT pers_id, UPPER(last_name) AS ln, UPPER(first_name) AS fn, birth_dt
      FROM cur_person WHERE birth_dt IS NOT NULL) p
JOIN (SELECT UPPER(last_name) AS ln, UPPER(first_name) AS fn, birth_dt
      FROM cur_person WHERE birth_dt IS NOT NULL
      GROUP BY UPPER(last_name), UPPER(first_name), birth_dt
      HAVING COUNT(DISTINCT pers_id) > 1 AND COUNT(DISTINCT natl_id_hash) > 1) g
  ON g.ln = p.ln AND g.fn = p.fn AND g.birth_dt = p.birth_dt;

-- P03 [high] Overlapping person history rows
SELECT DISTINCT 'person' AS entity_type, x.pers_id AS entity_id,
       'row ending ' || CAST(x.exp_dt AS VARCHAR(30)) || ' overlaps next row starting ' || CAST(x.nxt AS VARCHAR(30)) AS detail
FROM (SELECT pers_id, exp_dt, LEAD(eff_dt) OVER (PARTITION BY pers_id ORDER BY eff_dt, exp_dt) AS nxt
      FROM stg_person) x
WHERE x.nxt IS NOT NULL AND x.nxt <= x.exp_dt;

-- P04 [medium] Active worker with no birth date
SELECT 'person' AS entity_type, e.pers_id AS entity_id, 'active worker, birth date missing' AS detail
FROM active_worker e JOIN cur_person p ON p.pers_id = e.pers_id
WHERE p.birth_dt IS NULL;

-- P05 [critical] Employee history with no person record
SELECT DISTINCT 'person' AS entity_type, e.pers_id AS entity_id, 'employee rows but no T_PERS_HIST row' AS detail
FROM stg_employee e
WHERE NOT EXISTS (SELECT 1 FROM stg_person p WHERE p.pers_id = e.pers_id);

-- E01 [critical] Overlapping employee status intervals
SELECT DISTINCT 'person' AS entity_type, x.pers_id AS entity_id,
       'employee row ending ' || CAST(x.exp_dt AS VARCHAR(30)) || ' overlaps row starting ' || CAST(x.nxt AS VARCHAR(30)) AS detail
FROM (SELECT pers_id, exp_dt, LEAD(eff_dt) OVER (PARTITION BY pers_id ORDER BY eff_dt, exp_dt) AS nxt
      FROM stg_employee) x
WHERE x.nxt IS NOT NULL AND x.nxt <= x.exp_dt;

-- E02 [high] Gap in employee history
SELECT DISTINCT 'person' AS entity_type, x.pers_id AS entity_id,
       'no employee row between ' || CAST(x.exp_next_dt AS VARCHAR(30)) || ' and ' || CAST(x.nxt AS VARCHAR(30)) AS detail
FROM (SELECT pers_id, exp_next_dt, LEAD(eff_dt) OVER (PARTITION BY pers_id ORDER BY eff_dt, exp_dt) AS nxt
      FROM stg_employee) x
WHERE x.nxt IS NOT NULL AND x.nxt > x.exp_next_dt;

-- E03 [critical] Terminated employee with an active job
SELECT DISTINCT 'person' AS entity_type, e.pers_id AS entity_id,
       'employee status T since ' || CAST(e.eff_dt AS VARCHAR(30)) || ' but job ' || j.posn_nbr || ' active' AS detail
FROM cur_emp e JOIN cur_job j ON j.pers_id = e.pers_id
WHERE e.status_cd = 'T';

-- E04 [high] Termination record but employee still active
SELECT DISTINCT 'person' AS entity_type, e.pers_id AS entity_id,
       'termination dated ' || CAST(t.term_dt AS VARCHAR(30)) || ' but status ' || e.status_cd AS detail
FROM cur_emp e JOIN stg_termination t ON t.pers_id = e.pers_id
WHERE e.status_cd IN ('A', 'L') AND t.term_dt >= e.eff_dt AND t.term_dt <= DATE '2026-10-31';

-- E05 [medium] First hire date after current hire date
SELECT DISTINCT 'person' AS entity_type, pers_id AS entity_id,
       'first hire ' || CAST(first_hire_dt AS VARCHAR(30)) || ' > current hire ' || CAST(cur_hire_dt AS VARCHAR(30)) AS detail
FROM stg_employee WHERE first_hire_dt > cur_hire_dt;

-- E06 [high] Active employee with no active job
SELECT 'person' AS entity_type, e.pers_id AS entity_id, 'employee status ' || e.status_cd || ' with no active job' AS detail
FROM cur_emp e
WHERE e.status_cd IN ('A', 'L') AND NOT EXISTS (SELECT 1 FROM cur_job j WHERE j.pers_id = e.pers_id);

-- E07 [high] Employee class not in the employee-class reference (PTRECLS)
SELECT 'person' AS entity_type, e.pers_id AS entity_id, 'employee class ' || COALESCE(e.ecls_cd, '(null)') || ' not in reference' AS detail
FROM cur_emp e
WHERE e.status_cd IN ('A', 'L') AND NOT EXISTS (SELECT 1 FROM ref_ecls r WHERE r.ecls_cd = e.ecls_cd);

-- E08 [medium] Employee row dated beyond the pending-action horizon
SELECT DISTINCT 'person' AS entity_type, pers_id AS entity_id, 'employee row effective ' || CAST(eff_dt AS VARCHAR(30)) AS detail
FROM stg_employee WHERE eff_dt > DATE '2027-04-29';

-- J01 [critical] Overlapping job detail intervals
SELECT DISTINCT 'job' AS entity_type, x.pers_id || '|' || x.posn_nbr || '|' || x.suffix AS entity_id,
       'row ending ' || CAST(x.exp_dt AS VARCHAR(30)) || ' overlaps row starting ' || CAST(x.nxt AS VARCHAR(30)) AS detail
FROM (SELECT pers_id, posn_nbr, suffix, exp_dt,
             LEAD(eff_dt) OVER (PARTITION BY pers_id, posn_nbr, suffix ORDER BY eff_dt, exp_dt) AS nxt
      FROM stg_job) x
WHERE x.nxt IS NOT NULL AND x.nxt <= x.exp_dt;

-- J02 [high] Gap in job detail history
SELECT DISTINCT 'job' AS entity_type, x.pers_id || '|' || x.posn_nbr || '|' || x.suffix AS entity_id,
       'no job row between ' || CAST(x.exp_next_dt AS VARCHAR(30)) || ' and ' || CAST(x.nxt AS VARCHAR(30)) AS detail
FROM (SELECT pers_id, posn_nbr, suffix, exp_next_dt,
             LEAD(eff_dt) OVER (PARTITION BY pers_id, posn_nbr, suffix ORDER BY eff_dt, exp_dt) AS nxt
      FROM stg_job) x
WHERE x.nxt IS NOT NULL AND x.nxt > x.exp_next_dt;

-- J03 [critical] Job row expires before it starts
SELECT DISTINCT 'job' AS entity_type, pers_id || '|' || posn_nbr || '|' || suffix AS entity_id,
       'eff ' || CAST(eff_dt AS VARCHAR(30)) || ' > exp ' || CAST(exp_dt AS VARCHAR(30)) AS detail
FROM stg_job WHERE exp_dt < eff_dt;

-- J04 [critical] More than one active primary job
SELECT 'person' AS entity_type, pers_id AS entity_id, CAST(COUNT(*) AS VARCHAR(10)) || ' active primary jobs' AS detail
FROM cur_job WHERE contract_type = 'P'
GROUP BY pers_id HAVING COUNT(*) > 1;

-- J05 [high] Active secondary/overload job without a primary job
SELECT 'person' AS entity_type, pers_id AS entity_id, 'active jobs but none primary' AS detail
FROM cur_job
GROUP BY pers_id
HAVING SUM(CASE WHEN contract_type = 'P' THEN 1 ELSE 0 END) = 0;

-- J06 [critical] Single job FTE above 1.0
SELECT 'job' AS entity_type, job_key AS entity_id, 'FTE ' || CAST(fte AS VARCHAR(20)) AS detail
FROM cur_job WHERE fte > 1;

-- J07 [high] Person's total active FTE above 1.0
SELECT 'person' AS entity_type, pers_id AS entity_id, 'total active FTE ' || CAST(SUM(fte) AS VARCHAR(20)) AS detail
FROM cur_job GROUP BY pers_id HAVING SUM(fte) > 1;

-- J08 [medium] Job row dated beyond the pending-action horizon
SELECT DISTINCT 'job' AS entity_type, pers_id || '|' || posn_nbr || '|' || suffix AS entity_id,
       'job row effective ' || CAST(eff_dt AS VARCHAR(30)) AS detail
FROM stg_job WHERE eff_dt > DATE '2027-04-29';

-- S01 [medium] Orphan position (active, older than 24 months, no incumbent in 24 months)
SELECT 'position' AS entity_type, p.posn_nbr AS entity_id, 'active, no incumbent since before ' || CAST(DATE '2024-10-31' AS VARCHAR(30)) AS detail
FROM cur_posn p
WHERE p.status_cd = 'A'
  AND (SELECT MIN(h.eff_dt) FROM stg_position h WHERE h.posn_nbr = p.posn_nbr) < DATE '2024-10-31'
  AND NOT EXISTS (SELECT 1 FROM stg_job j WHERE j.posn_nbr = p.posn_nbr AND j.status_cd IN ('A', 'L')
                  AND j.eff_dt <= DATE '2026-10-31' AND j.exp_dt >= DATE '2024-10-31');

-- S02 [high] Position over-filled (incumbent FTE above budgeted FTE)
SELECT 'position' AS entity_type, p.posn_nbr AS entity_id,
       'incumbent FTE ' || CAST(SUM(j.fte) AS VARCHAR(20)) || ' > budget ' || CAST(MAX(p.budget_fte) AS VARCHAR(20)) AS detail
FROM cur_posn p JOIN cur_job j ON j.posn_nbr = p.posn_nbr
GROUP BY p.posn_nbr HAVING SUM(j.fte) > MAX(p.budget_fte);

-- S03 [high] Overlapping position history rows
SELECT DISTINCT 'position' AS entity_type, x.posn_nbr AS entity_id,
       'row ending ' || CAST(x.exp_dt AS VARCHAR(30)) || ' overlaps row starting ' || CAST(x.nxt AS VARCHAR(30)) AS detail
FROM (SELECT posn_nbr, exp_dt, LEAD(eff_dt) OVER (PARTITION BY posn_nbr ORDER BY eff_dt, exp_dt) AS nxt
      FROM stg_position) x
WHERE x.nxt IS NOT NULL AND x.nxt <= x.exp_dt;

-- S04 [critical] Job references a position missing from position control
SELECT DISTINCT 'job' AS entity_type, j.pers_id || '|' || j.posn_nbr || '|' || j.suffix AS entity_id,
       'position ' || j.posn_nbr || ' not in position history' AS detail
FROM stg_job j
WHERE NOT EXISTS (SELECT 1 FROM stg_position p WHERE p.posn_nbr = j.posn_nbr);

-- S05 [high] Active job on an inactive position
SELECT 'job' AS entity_type, j.job_key AS entity_id, 'position status ' || p.status_cd AS detail
FROM cur_job j JOIN cur_posn p ON p.posn_nbr = j.posn_nbr
WHERE p.status_cd <> 'A';

-- S06 [medium] Job org differs from its position's org
SELECT 'job' AS entity_type, j.job_key AS entity_id, 'job org ' || j.org_cd || ' vs position org ' || p.org_cd AS detail
FROM cur_job j JOIN cur_posn p ON p.posn_nbr = j.posn_nbr
WHERE j.org_cd <> p.org_cd;

-- S07 [medium] Job class differs from its position's class
SELECT 'job' AS entity_type, j.job_key AS entity_id, 'job class ' || j.class_cd || ' vs position class ' || p.class_cd AS detail
FROM cur_job j JOIN cur_posn p ON p.posn_nbr = j.posn_nbr
WHERE j.class_cd <> p.class_cd;

-- C01 [critical] Civil-service job class not in the SUCSS catalog
SELECT 'job' AS entity_type, j.job_key AS entity_id, 'class ' || COALESCE(j.class_cd, '(null)') || ' not in SUCSS catalog' AS detail
FROM cur_job j JOIN ref_ecls e ON e.ecls_cd = j.ecls_cd
WHERE e.ecls_group = 'CS' AND j.class_cd IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM ref_class c WHERE c.class_cd = j.class_cd AND c.class_source = 'SUCSS');

-- C02 [high] Salary below the class range minimum (full-time equivalent)
SELECT 'job' AS entity_type, j.job_key AS entity_id,
       'FTE rate ' || CAST(CAST(j.annual_sal / j.fte AS DECIMAL(14,2)) AS VARCHAR(20)) || ' < min ' || CAST(c.min_annual AS VARCHAR(20)) AS detail
FROM cur_job j
JOIN ref_ecls e ON e.ecls_cd = j.ecls_cd
JOIN ref_class c ON c.class_cd = j.class_cd
WHERE e.pay_basis = 'SAL' AND j.fte > 0 AND j.annual_sal / j.fte < c.min_annual;

-- C03 [medium] Salary above the class range maximum (full-time equivalent)
SELECT 'job' AS entity_type, j.job_key AS entity_id,
       'FTE rate ' || CAST(CAST(j.annual_sal / j.fte AS DECIMAL(14,2)) AS VARCHAR(20)) || ' > max ' || CAST(c.max_annual AS VARCHAR(20)) AS detail
FROM cur_job j
JOIN ref_ecls e ON e.ecls_cd = j.ecls_cd
JOIN ref_class c ON c.class_cd = j.class_cd
WHERE e.pay_basis = 'SAL' AND j.fte > 0 AND j.annual_sal / j.fte > c.max_annual;

-- C04 [high] Active job with no class code
SELECT 'job' AS entity_type, job_key AS entity_id, 'class code missing' AS detail
FROM cur_job WHERE class_cd IS NULL;

-- O01 [critical] Active primary job with no supervisor
SELECT 'person' AS entity_type, j.pers_id AS entity_id, 'primary job ' || j.posn_nbr || ' has no supervisor' AS detail
FROM cur_job j
WHERE j.contract_type = 'P' AND j.supervisor_pers_id IS NULL
  AND NOT EXISTS (SELECT 1 FROM ref_hierarchy_root r WHERE r.posn_nbr = j.posn_nbr);

-- O02 [high] Supervisor is not an active worker
SELECT 'person' AS entity_type, j.pers_id AS entity_id, 'supervisor ' || j.supervisor_pers_id || ' not active' AS detail
FROM cur_job j
WHERE j.contract_type = 'P' AND j.supervisor_pers_id IS NOT NULL AND j.supervisor_pers_id <> j.pers_id
  AND NOT EXISTS (SELECT 1 FROM active_worker a WHERE a.pers_id = j.supervisor_pers_id);

-- O03 [critical] Cycle in reporting lines
WITH RECURSIVE edges (pers_id, sup_id) AS (
  SELECT DISTINCT pers_id, supervisor_pers_id FROM cur_job
  WHERE contract_type = 'P' AND supervisor_pers_id IS NOT NULL AND supervisor_pers_id <> pers_id
),
walk (start_id, cur_id, depth) AS (
  SELECT pers_id, sup_id, 1 FROM edges
  UNION ALL
  SELECT w.start_id, e.sup_id, w.depth + 1
  FROM walk w JOIN edges e ON e.pers_id = w.cur_id
  WHERE w.depth < 30 AND w.cur_id <> w.start_id
)
SELECT 'person' AS entity_type, start_id AS entity_id,
       'reporting cycle of length ' || CAST(MIN(depth) AS VARCHAR(10)) AS detail
FROM walk WHERE cur_id = start_id AND depth >= 2
GROUP BY start_id;

-- O04 [high] Person supervises themselves
SELECT 'person' AS entity_type, pers_id AS entity_id, 'supervisor is self' AS detail
FROM cur_job WHERE contract_type = 'P' AND supervisor_pers_id = pers_id;

-- O05 [medium] Org whose parent org does not exist
SELECT 'org' AS entity_type, o.org_cd AS entity_id, 'parent ' || o.parent_org_cd || ' missing' AS detail
FROM ref_org o
WHERE o.parent_org_cd IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ref_org p WHERE p.org_cd = o.parent_org_cd);

-- O06 [high] Active job or position uses an unknown or inactive org
SELECT 'org' AS entity_type, u.org_cd AS entity_id, 'referenced by active job/position; unknown or inactive' AS detail
FROM (SELECT org_cd FROM cur_job UNION SELECT org_cd FROM cur_posn WHERE status_cd = 'A') u
WHERE NOT EXISTS (SELECT 1 FROM ref_org o WHERE o.org_cd = u.org_cd AND o.status_cd = 'A');

-- Y01 [high] Pay with no job record for the same person, position and suffix
SELECT DISTINCT 'pay' AS entity_type,
       y.pers_id || '|' || y.posn_nbr || '|' || y.suffix || '|' || CAST(y.period_end_dt AS VARCHAR(30)) AS entity_id,
       'no job record for this person/position/suffix' AS detail
FROM stg_pay y
WHERE NOT EXISTS (SELECT 1 FROM stg_job j WHERE j.pers_id = y.pers_id AND j.posn_nbr = y.posn_nbr AND j.suffix = y.suffix);

-- Y02 [critical] Pay after termination without rehire
SELECT DISTINCT 'pay' AS entity_type,
       y.pers_id || '|' || y.posn_nbr || '|' || y.suffix || '|' || CAST(y.period_end_dt AS VARCHAR(30)) AS entity_id,
       'employee status T on period end' AS detail
FROM stg_pay y JOIN stg_employee e
  ON e.pers_id = y.pers_id AND e.eff_dt <= y.period_end_dt AND e.exp_dt >= y.period_end_dt
WHERE e.status_cd = 'T';

-- Y03 [high] Pay charged to a position missing from position control
SELECT DISTINCT 'pay' AS entity_type,
       y.pers_id || '|' || y.posn_nbr || '|' || y.suffix || '|' || CAST(y.period_end_dt AS VARCHAR(30)) AS entity_id,
       'position ' || y.posn_nbr || ' not in position history' AS detail
FROM stg_pay y
WHERE NOT EXISTS (SELECT 1 FROM stg_position p WHERE p.posn_nbr = y.posn_nbr);

-- Y04 [medium] Negative net pay for a person and period
SELECT 'pay' AS entity_type, pers_id || '|' || CAST(period_end_dt AS VARCHAR(30)) AS entity_id,
       'net pay ' || CAST(SUM(amount) AS VARCHAR(20)) AS detail
FROM stg_pay GROUP BY pers_id, period_end_dt HAVING SUM(amount) < 0;

-- Y05 [high] Duplicate pay accounting rows
SELECT DISTINCT 'pay' AS entity_type,
       pers_id || '|' || posn_nbr || '|' || suffix || '|' || CAST(period_end_dt AS VARCHAR(30)) AS entity_id,
       CAST(COUNT(*) AS VARCHAR(10)) || ' identical rows for earn code ' || earn_cd AS detail
FROM stg_pay
GROUP BY pers_id, posn_nbr, suffix, period_end_dt, earn_cd, amount
HAVING COUNT(*) > 1;
